#include "stdafx.h"#include "HcdElementBase.h"struct SNOT_P{#include "PrivateVars/NOT.h"};class KNOT : public KHcdElementBase  , protected SNOT_P{public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _NOT("NOT", KNOT::Create);IHcdElement *KNOT::Create(){  return new KNOT;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KNOT, 2 )void KNOT::InitParm(){#include "PrivateVars/NOT.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KNOT::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}void KNOT::StepCalc( SStepCalcParams &params ){  OUTR0 = INL0 ? 0 : 1;}